 const saveExperiment=()=>{if(!result){note("Сначала выполни граф");return}const entry={id:makeId(),name:`${settings.model||"model"} · ${new Date().toLocaleString(locale)}`,model:settings.model,provider:settings.provider,systemPrompt:promptPreview.resolvedSys,prompt:promptPreview.resolvedUser,rawPrompt:promptPreview.user,settings:{endpoint:settings.endpoint,temperature:settings.temperature,topP:settings.topP,maxTokens:settings.maxTokens,contextTokens:settings.contextTokens},results:[{model:settings.model,provider:settings.provider,endpoint:settings.endpoint,response:result,error:null,durationMs:metrics?.elapsedMs??metrics?.totalMs??null,usage:{promptTokens:metrics?.promptTokens??null,completionTokens:metrics?.completionTokens??null}}],response:result,metrics,trace,createdAt:new Date().toISOString(),rating:0,notes:""};setExperiments(xs=>[entry,...xs]);note("Результат эксперимента сохранён локально")};
